            px, py = p.position.x, p.position.y
            fx, fy = 0.0, 0.0
            if (11.0 <= px <= 12.5) or (10.0 <= px <= 14.0 and 1.5 <= py <= 3.5):
                if py < 2.0:
                    fy = 150.0
                if px < 18.0:
                    fx = 300.0
                if py > 3.0:
                    fx += 150.0
            elif px < 6.0:
                fx = 250.0
                if py < 1.5:
                    fy = 15.0
                elif py > 1.5:
                    fy = -15.0
            elif 6.0 <= px <= 18.0:
                fx = 300.0
                if py < 1.5:
                    fy = 15.0
                elif py > 1.5:
                    fy = -15.0
                if 10.0 <= px <= 14.0 and 1.5 <= py <= 3.5:
                    fy += 200.0
                if py > 3.0:
                    fx += 150.0
            elif 18.0 <= px <= 22.0:
                if abs(p.linearVelocity.x) > 0.2:
                    fx = -15.0 * p.linearVelocity.x
                if p.linearVelocity.y > 0:
                    fy = -15.0
                elif p.linearVelocity.y < 0:
                    fy = 15.0
                if p.position.y > 1.5:
                    fy -= 15.0
                elif p.position.y < 0:
                    fy += 15.0
                if p.position.y > 3.0:
                    fx = -150.0
            sandbox.apply_force_to_particle(p, fx, fy)
